#define _GNU_SOURCE
#include <dlfcn.h>
#include <time.h>

int clock_gettime(clockid_t clock, struct timespec *time) {
    if (clock == CLOCK_REALTIME) {
        time->tv_sec = 1794417600;
        time->tv_nsec = 0;
        return 0;
    }
    int (*actual)(clockid_t, struct timespec *) = dlsym(RTLD_NEXT, "clock_gettime");
    return actual(clock, time);
}
